import { Component, createMemo, Show } from "solid-js";

import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { TooltipKeyword } from "#core/ui-next/components/tooltip-keyword.jsx";
import { Tooltip } from "#core/ui-next/components/tooltip.jsx";

import { TicketRow, TicketSection } from "#base/ui-next/tooltips/plot-tooltip/components/utility.jsx";
import { getTreasureConvoyInfo } from "#base/ui-next/tooltips/plot-tooltip/helpers.js";

/** Props for {@link TreasureConvoySection}. */
export interface TreasureConvoySectionProps {
	/** The city that owns the plot, if any. Used to read convoy generation timing. */
	owningCity: City | null;
	/** Whether the plot is in the local player's distant lands. Determines the icon shown. */
	isDistantLands: boolean;
}

/**
 * Treasure convoy generation status for a settled treasure-resource plot.
 *
 * Visually mirrors the gold timed-alert ticket but is a standalone section because
 * convoy generation is not actually an alert.
 */
export const TreasureConvoySection: Component<TreasureConvoySectionProps> = (props) => {
	const convoy = createMemo(() => getTreasureConvoyInfo(props.owningCity));

	return (
		<TicketSection
			name="TreasureConvoySection"
			variant="gold"
		>
			<TicketRow
				icon={
					<Icon
						class="size-8"
						name={`url(blp:${props.isDistantLands ? "restype_treasure_v2" : "restype_treasure_v3"})`}
						isUrl
					/>
				}
			>
				<div class="flex">
					<Tooltip.Text text="LOC_PEDIA_CONCEPTS_TREASURE_RESOURCES_TOOLTIP">
						<TooltipKeyword class="flex-auto">
							<L10n.Stylize
								class="font-title text-sm uppercase"
								text="LOC_PLOT_TOOLTIP_TREASURE_RESOURCE"
							/>
						</TooltipKeyword>
					</Tooltip.Text>
					<Show when={convoy()?.turnsRemaining != null}>
						<div class="flex flex-col items-center ml-2 shrink-0">
							<div
								class="size-6 bg-contain bg-center bg-no-repeat"
								style={{ "background-image": "url(blp:hud_turn-timer)" }}
							/>
							<span class="font-body text-xs text-accent-2">{convoy()!.turnsRemaining}</span>
						</div>
					</Show>
				</div>
			</TicketRow>
		</TicketSection>
	);
};
